---
// Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync.
// Eval radar: This run against the baseline on six eval scores, with the weak ones flagged.
// The markup, CSS and script are designme.dev's own, run by the shared core in ../core, which mounts the component when it scrolls
// into view and plays its demo. To show your own data, change radar-chart.js. The markup is kept exactly as it is (is:raw).
import type { HTMLAttributes } from 'astro/types';
import '../core/designme.css';
import './radar-chart.css';

export interface Props extends HTMLAttributes<'div'> {
  /** "soft" draws it in the Soft style. Leave it out for Blueprint, or for the style set on <html> (data-style="soft") */
  'data-style'?: 'soft';
}
const { class: className, ...rest } = Astro.props;
---
<div class:list={['card', className]} data-c="radar-chart" {...rest}>
  <div class="stage-in"><Fragment is:raw>
<div class="rdx panel">
  <div class="rdx-h">
    <div class="rdx-t"><b>Eval scores</b><span class="muted">Run 48 against run 41</span></div>
    <div class="rdx-lg"><button class="rdx-k" aria-pressed="true" data-s="cur"><i class="c"></i>This run</button><button class="rdx-k" aria-pressed="true" data-s="base"><i class="b"></i>Baseline</button></div>
  </div>
  <div class="rdx-ch" role="group" aria-label="Scores by axis. Left and Right move between axes">
    <svg class="rdx-svg" aria-hidden="true"></svg>
    <span class="rdx-avg num"><b>0</b><span class="muted">average</span></span>
  </div>
  <div class="rdx-ro" aria-live="polite"><span></span></div>
</div>
  </Fragment></div>
</div>
<script>
  import './radar-chart.js';
</script>

/* Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync. */
/* ---------- Eval radar ---------- */
/* the baseline as an outline, this run filled over it, on grey scale rings; each axis is a label you can point at or tab to */
.rdx{padding:var(--dm-s-4);display:flex;flex-direction:column;gap:var(--dm-s-2);container-type:inline-size}
.rdx-h{display:flex;align-items:flex-start;justify-content:space-between;gap:10px;flex-wrap:wrap}
.rdx-t{display:flex;flex-direction:column;font-size:13.5px;line-height:1.4}
.rdx-t b{font-weight:500}
.rdx-t .muted{font-size:12px}
.rdx-lg{display:flex;gap:var(--dm-s-1)}
.rdx-k{display:flex;align-items:center;gap:6px;height:26px;padding:0 9px;border-radius:var(--dm-r-pill);font-size:12px;color:var(--dm-muted);transition:color .2s,background .2s}
@media (hover:hover) and (pointer:fine){.rdx-k:hover{background:var(--dm-row)}}
.rdx-k[aria-pressed="true"]{color:var(--dm-fg)}
.rdx-k i{width:10px;height:10px;border-radius:50%;transition:opacity .3s,transform .3s var(--dm-ease)}
.rdx-k i.c{background:color-mix(in srgb,var(--dm-c1) 22%,transparent);box-shadow:inset 0 0 0 1.5px var(--dm-c1)}
.rdx-k i.b{box-shadow:inset 0 0 0 1.5px var(--dm-c2)}
.rdx-k[aria-pressed="false"] i{opacity:.3;transform:scale(.7)}
.rdx-ch{position:relative;height:280px}
.rdx-svg{position:absolute;inset:0;width:100%;height:100%;overflow:visible}
.rdx-svg .ring{fill:none;stroke:color-mix(in srgb,var(--dm-line) 50%,transparent);stroke-width:1}
.rdx-svg .ring.out{stroke:var(--dm-line)}
.rdx-svg .sp{stroke:color-mix(in srgb,var(--dm-line) 50%,transparent);stroke-width:1;transition:stroke .2s}
.rdx-svg .sp.on{stroke:var(--dm-faint)}
.rdx-svg .base{fill:none;stroke:var(--dm-c2);stroke-width:1.5;stroke-linejoin:round;transition:opacity .3s}
.rdx-svg .cur{fill:color-mix(in srgb,var(--dm-c1) 16%,transparent);stroke:var(--dm-c1);stroke-width:2;stroke-linejoin:round;transition:opacity .3s}
.rdx-svg .off{opacity:0}
.rdx-svg .pt{fill:var(--dm-surface);stroke-width:2;transition:opacity .3s,r .2s var(--dm-ease)}
.rdx-svg .pt.c{stroke:var(--dm-c1)}.rdx-svg .pt.b{stroke:var(--dm-c2)}
.rdx-svg .pt.on{r:4.5}
.rdx-avg{position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);display:flex;flex-direction:column;align-items:center;padding:2px var(--dm-s-2);border-radius:calc(8px * var(--dm-rk));background:color-mix(in srgb,var(--dm-surface) 82%,transparent);line-height:1.25;pointer-events:none}
.rdx-avg b{font-size:14px;font-weight:500}
.rdx-avg .muted{font-size:11px}
/* an axis: its name, this run's score and how far it moved; a weak one says so in words */
.rdx-ax{position:absolute;display:flex;flex-direction:column;gap:1px;max-width:92px;padding:3px 6px;border-radius:calc(7px * var(--dm-rk));font-size:12px;line-height:1.3;color:var(--dm-fg2);transition:background var(--dm-t-fast),color var(--dm-t-fast)}
.rdx-ax .v{display:flex;align-items:center;gap:4px;font-size:11.5px;color:var(--dm-muted);white-space:nowrap}
.rdx-ax .v b{font-weight:500;color:var(--dm-fg)}
.rdx-ax .tag{height:16px;padding:0 5px;font-size:10.5px}
.rdx-ax.l{text-align:right;align-items:flex-end}.rdx-ax.m{text-align:center;align-items:center}
.rdx-ax.on{background:var(--dm-row);color:var(--dm-fg)}
@media (hover:hover) and (pointer:fine){.rdx-ax:hover{background:var(--dm-row);color:var(--dm-fg)}}
.rdx-ax.hot{animation:rdxpulse 1.1s var(--dm-ease-io) 3}
@keyframes rdxpulse{50%{transform:scale(1.06);background:var(--dm-row)}}
.rdx-ro{min-height:56px;display:flex;align-items:center;gap:var(--dm-s-2);padding:var(--dm-s-2) var(--dm-s-3);border-radius:var(--dm-r-in);background:var(--dm-row);font-size:12.5px;color:var(--dm-fg2)}
.rdx-ro>span{display:flex;align-items:center;gap:var(--dm-s-2)}
.rdx-ro .i{flex:none;color:var(--dm-accent-fg,var(--dm-accent))}
.rdx-ro b{font-weight:500;color:var(--dm-fg)}
.rdx-ro .dn{color:var(--dm-bad)}.rdx-ro .up{color:var(--dm-ok)}
:root:not([data-style="soft"]) .rdx-svg .ring.out:not(:where([data-style="soft"],[data-style="soft"] *)){stroke:var(--dm-rail)}
/* on a phone the labels stack their parts, so the rings get more room, and the average gives way to them */
@container (max-width:300px){.rdx-ax{max-width:68px}.rdx-ax .v{flex-wrap:wrap;justify-content:inherit}.rdx-ax.l .v{justify-content:flex-end}.rdx-ax.m .v{justify-content:center}.rdx-avg{display:none}.rdx-ch{height:260px}}

// Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync.
import { $, $$, DM, I, swap, tween } from '../core/core.js';
DM.def('radar-chart', (r, c) => {
  // six eval scores out of 100: this run against the baseline it is compared with
  const A = [['Accuracy', 88, 84], ['Instruction following', 86, 80], ['Tool use', 62, 78], ['Speed', 74, 66], ['Cost efficiency', 82, 58], ['Safety', 91, 90]];
  const WEAK = 70, N = A.length;
  const ch = $('.rdx-ch', r), svg = $('.rdx-svg', r), avg = $('.rdx-avg b', r), ro = $('.rdx-ro span', r), keys = $$('.rdx-k', r);
  const mean = k => Math.round(A.reduce((t, a) => t + a[k], 0) / N);
  ch.insertAdjacentHTML('beforeend', A.map((a, i) => `<button class="rdx-ax" data-i="${i}" tabindex="${i ? -1 : 0}" aria-label="${a[0]}: ${a[1]}, baseline ${a[2]}, ${a[1] >= a[2] ? 'up' : 'down'} ${Math.abs(a[1] - a[2])}${a[1] < WEAK ? ', weak' : ''}"><span class="n">${a[0]}</span><span class="v num"><b>${a[1]}</b><span>${a[1] >= a[2] ? '+' : '−'}${Math.abs(a[1] - a[2])}</span>${a[1] < WEAK ? '<span class="tag warn">Weak</span>' : ''}</span></button>`).join(''));
  const L = $$('.rdx-ax', ch);
  let grow = 0, drawn = 0, on = { cur:true, base:true }, hot = -1, G = null;
  // the geometry follows the chart's size, so the labels always sit outside the rings
  // on a narrow card the long names shorten, and the rings take whatever room the side labels leave
  const SHORT = ['Accuracy', 'Instructions', 'Tool use', 'Speed', 'Cost', 'Safety'];
  function geo(){ const W = ch.clientWidth, H = ch.clientHeight, narrow = W < 380;
    L.forEach((l, i) => { const t = narrow ? SHORT[i] : A[i][0], n = $('.n', l); if (n.textContent !== t) n.textContent = t; });
    const side = Math.max(...L.filter((l, i) => Math.abs(Math.cos(ang(i))) >= .2).map(l => l.offsetWidth));
    const R = Math.max(40, Math.min(H / 2 - 46, W / 2 - side - 14)); return { W, H, cx:W / 2, cy:H / 2, R }; }
  const ang = i => -Math.PI / 2 + i * 2 * Math.PI / N;
  const pt = (g, i, v) => [g.cx + Math.cos(ang(i)) * g.R * v / 100, g.cy + Math.sin(ang(i)) * g.R * v / 100];
  const poly = (g, k, s = 1) => A.map((a, i) => pt(g, i, a[k] * s).map(n => n.toFixed(1)).join(',')).join(' ');
  function draw(){
    G = geo(); const g = G; svg.setAttribute('viewBox', `0 0 ${g.W} ${g.H}`);
    svg.innerHTML = [25, 50, 75, 100].map(v => `<polygon class="ring${v === 100 ? ' out' : ''}" points="${A.map((a, i) => pt(g, i, v).join(',')).join(' ')}"/>`).join('')
      + A.map((a, i) => { const [x, y] = pt(g, i, 100); return `<line class="sp" x1="${g.cx}" y1="${g.cy}" x2="${x}" y2="${y}"/>`; }).join('')
      + `<polygon class="base${on.base ? '' : ' off'}" pathLength="100" style="stroke-dasharray:${drawn} 100" points="${poly(g, 2)}"/>`
      + `<polygon class="cur${on.cur ? '' : ' off'}" points="${poly(g, 1, grow)}"/>`
      + A.map((a, i) => { const [bx, by] = pt(g, i, a[2]), [x, y] = pt(g, i, a[1] * grow); return `<circle class="pt b${on.base && drawn >= 100 ? '' : ' off'}" r="2.5" cx="${bx}" cy="${by}"/><circle class="pt c${on.cur && grow > .98 ? '' : ' off'}${i === hot ? ' on' : ''}" r="3" cx="${x}" cy="${y}"/>`; }).join('');
    $$('.sp', svg).forEach((s, i) => s.classList.toggle('on', i === hot));
    L.forEach((l, i) => { const a = ang(i), x = g.cx + Math.cos(a) * (g.R + 12), y = g.cy + Math.sin(a) * (g.R + 12), cs = Math.cos(a), sn = Math.sin(a);
      const side = Math.abs(cs) < .2 ? 'm' : cs < 0 ? 'l' : 'r'; l.classList.remove('l', 'm', 'r'); l.classList.add(side);
      const w = l.offsetWidth, h = l.offsetHeight;
      l.style.left = (side === 'm' ? x - w / 2 : side === 'l' ? x - w : x) + 'px'; l.style.top = (Math.abs(sn) > .9 ? (sn < 0 ? y - h : y) : y - h / 2) + 'px'; });
  }
  const ro2 = new ResizeObserver(draw); ro2.observe(ch); c.offs.push(() => ro2.disconnect());
  // the line under the chart: the axis in hand with both scores and the change, or else the agent's note
  let note = `${I('spark','xs')}<span>Run 48 averages <b>${mean(1)}</b>, up ${mean(1) - mean(2)} on the baseline.</span>`;
  const show = i => { hot = i; L.forEach((l, j) => l.classList.toggle('on', j === i)); draw();
    if (i < 0){ swap(ro, note, true); return; }
    const [n, a, b] = A[i], d = a - b; swap(ro, `<span><b>${n}</b> ${a} now, ${b} before, <span class="${d < 0 ? 'dn' : 'up'}">${d < 0 ? '−' : '+'}${Math.abs(d)}</span>${a < WEAK ? ', below 70' : ''}</span>`, true); };
  L.forEach((l, i) => { c.on(l, 'pointerenter', e => { if (e.pointerType !== 'touch') show(i); }); c.on(l, 'focus', () => show(i)); c.on(l, 'click', () => show(i)); });
  c.on(ch, 'pointerleave', () => { if (!ch.contains(document.activeElement)) show(-1); });
  c.on(ch, 'focusout', e => { if (!ch.contains(e.relatedTarget)) show(-1); });
  // roving focus: one axis takes Tab, Left and Right (and Up and Down) go round the chart, Home and End to the first and last
  c.on(ch, 'keydown', e => { const i = L.indexOf(document.activeElement); if (i < 0) return;
    const to = { ArrowRight:i + 1, ArrowDown:i + 1, ArrowLeft:i - 1, ArrowUp:i - 1, Home:0, End:N - 1 }[e.key]; if (to == null) return;
    e.preventDefault(); const j = (to + N) % N; L.forEach((l, k) => l.tabIndex = k === j ? 0 : -1); L[j].focus(); });
  // the legend shows and hides a series; one always stays
  keys.forEach(k => k.onclick = () => { const s = k.dataset.s, o = s === 'cur' ? 'base' : 'cur'; if (on[s] && !on[o]) return; on[s] = !on[s]; k.setAttribute('aria-pressed', on[s]); draw(); });
  ro.innerHTML = '<span class="muted">Drawing the baseline</span>'; avg.textContent = '0';
  // the baseline draws itself, this run grows out of the middle, then the agent says what changed and points at tool use
  c.run(async () => {
    await c.wait(300);
    await tween(0, 100, 900, v => { drawn = v; draw(); });
    await c.wait(250);
    tween(0, mean(1), 1100, v => avg.textContent = Math.round(v));
    await tween(0, 1, 1100, v => { grow = v; draw(); });
    await c.wait(500);
    note = `${I('spark','xs')}<span>Cheaper and faster, <b>weaker at tool use</b> (−16). It skipped the search tool on 7 of 40 tasks.</span>`;
    if (hot < 0) swap(ro, note, true);
    const t = L[2]; t.classList.remove('hot'); void t.offsetWidth; t.classList.add('hot');
  });
  if (r === c.st) c.story(async s => {
    await s.beat(10);
    await s.point(L[2]); show(2); await s.beat(4);
    await s.point(L[4]); show(4); await s.beat(3);
    s.away(); show(-1); await s.beat(3);
  });
});
